fn solve(input: Vec<i8>) -> Vec<&'static str> {
    // Helper to check if n > 0 is a power of two.
    fn is_power_of_two(n: u32) -> bool {
        n != 0 && (n & (n - 1)) == 0
    }

    // "Limited-prime" as defined:
    // p <= 1           => not prime
    // p == 2           => prime
    // even p > 2       => not prime
    // odd p > 2        => prime
    fn is_limited_prime(p: u32) -> bool {
        p > 1 && (p == 2 || p % 2 == 1)
    }

    let mut result = Vec::new();

    if input.is_empty() {
        return result;
    }
    // The first element is the number of test cases.
    let t = input[0] as usize;
    // For each test case, read n and decide the winner.
    for i in 0..t {
        let n_i8 = input[i + 1];
        // Cast to unsigned for our bitwise & arithmetic checks
        let n = n_i8 as u8 as u32;

        let winner = if n == 1 {
            "FastestFinger"
        } else if n == 2 {
            "Ashishgup"
        } else if is_power_of_two(n) {
            // Any power of two > 2
            "FastestFinger"
        } else if n % 4 != 2 {
            // Covers all odd n > 2 and all multiples of 4
            "Ashishgup"
        } else {
            // n is even, not a power of two, and n % 4 == 2
            // Let p = n / 2
            let p = n / 2;
            if is_limited_prime(p) {
                "FastestFinger"
            } else {
                "Ashishgup"
            }
        };

        result.push(winner);
    }

    result
}